-- =====================================================================================================
-- ChatApp (RushDL - 13) - sample data (run after create_database.sql)
--   psql -v ON_ERROR_STOP=1 -d chatapp -f sample_data.sql
-- Rerunnable: it empties every table first.
--
-- Simulated use of the app from 2026-10-01 to 2026-11-19 12:00 (Asia/Ho_Chi_Minh), registrations through 2025-2026.
-- 24 users + 1 administrator, in three activity profiles:
--   highly active (almost every day, many opens and messages): mayachen, noahp, avab, isabelc, sofiareyes, lucasb
--   regular (most days, a day or two off in between):          ethanp, linhng, analopez, davelin, oliviar, khoatran, minhle, priyas
--   low / new (scattered activity):                            owentran, dkang, zoem, ryanh, tomwu, kevinm, quanph, hanab, jakeo, lilyv
-- Locked: linhng, owentran, ryanh. Deleted (soft): tomwu, kevinm. Temporarily locked and unlocked: ethanp, davelin.
-- 7 groups of 2-6 members; Java Study Group and Design Club are encrypted (key rotated after a member left or
-- was removed); Roommates turned encryption on and off again.
-- Every account's password is 'chatapp123'. Administrator: admin.
--
-- Formats (Version 2 must use the same, all binary values Base64):
--   password_hash          pbkdf2$<iterations>$<salt>$<hash>   PBKDF2WithHmacSHA256, 210000 iterations, 16-byte salt, 256-bit hash
--   user_key.public_key    RSA-2048 public key, X.509 SubjectPublicKeyInfo DER (Java X509EncodedKeySpec)
--   encrypted_private_key  IV(12) || AES-256-GCM(PKCS#8 DER private key), 128-bit tag;
--                          AES key = PBKDF2WithHmacSHA256(password, key_salt, 210000, 256 bits)
--   wrapped_key            RSA/ECB/OAEPWithSHA-256AndMGF1Padding with MGF1 SHA-256 (Java: OAEPParameterSpec)
--   encrypted content      IV(12) || AES-256-GCM(UTF-8 text), 128-bit tag, no associated data
-- This file is the team's official dataset: edit it directly and commit it; do not regenerate it.
-- =====================================================================================================

BEGIN;

SET TIME ZONE 'Asia/Ho_Chi_Minh';

TRUNCATE account_lock_log, group_event, group_key_share, user_key, app_open_event, login_history, spam_report,
    hidden_message, message, group_key, conversation_member, conversation, user_block, friendship, friend_request,
    user_account RESTART IDENTITY CASCADE;

