SELECT setval(pg_get_serial_sequence('user_account', 'id'), (SELECT max(id) FROM user_account));
SELECT setval(pg_get_serial_sequence('friend_request', 'id'), (SELECT max(id) FROM friend_request));
SELECT setval(pg_get_serial_sequence('conversation', 'id'), (SELECT max(id) FROM conversation));
SELECT setval(pg_get_serial_sequence('message', 'id'), (SELECT max(id) FROM message));
SELECT setval(pg_get_serial_sequence('spam_report', 'id'), (SELECT max(id) FROM spam_report));
SELECT setval(pg_get_serial_sequence('login_history', 'id'), (SELECT max(id) FROM login_history));
SELECT setval(pg_get_serial_sequence('app_open_event', 'id'), (SELECT max(id) FROM app_open_event));
SELECT setval(pg_get_serial_sequence('group_event', 'id'), (SELECT max(id) FROM group_event));
SELECT setval(pg_get_serial_sequence('account_lock_log', 'id'), (SELECT max(id) FROM account_lock_log));

